B=Block('a')
NUMERIC=[]
def verify(name,actual,expected):
 assert math.isclose(actual,expected,rel_tol=1e-10,abs_tol=1e-10),(name,actual,expected)
 NUMERIC.append(name)
def area(p,names):
 return abs(sum(p[names[i]][0]*p[names[(i+1)%len(names)]][1]-p[names[(i+1)%len(names)]][0]*p[names[i]][1] for i in range(len(names))))/2

def rectangle(a,b):
 p=rect(a,b);v=sc('ABCD',poly(),rightAngles=[rt('B','A','D')]);checks=[perp('A','B','A','D'),par('A','B','C','D'),par('A','D','B','C'),ratio('A','D','A','B',a/b)]
 return p,v,checks

def square(a):
 p,v,checks=rectangle(a,a);v['equalSegments']=[eq('A','B'),eq('B','C'),eq('C','D'),eq('D','A')]
 return p,v,checks+[equal(('A','B'),('B','C'),('C','D'),('D','A'))]

def para_height(a,h,shift=None):
 shift=a*.3 if shift is None else shift
 p=dict(A=[0,0],B=[shift,h],C=[shift+a,h],D=[a,0],H=[shift,0]);v=sc('ABCDH',poly()+[['B','H']],rightAngles=[rt('B','H','D')]);checks=para_checks()+[perp('B','H','A','D'),col('A','H','D'),ratio('A','D','B','H',a/h)]
 if shift>a or shift<0:v=more(v,dashSegments=[['A','H'],['D','H']])
 return p,v,checks

